import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, Download, PenLine, Save, Headphones, Play, Square, FileText, Image as ImageIcon, Wand2, Menu, X, Sparkles, Palette } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { generateSpeech, generateImage, refineChapterText } from '../services/gemini';
import { Notification } from './Notification';

// Declare html2pdf globally as it's loaded via CDN in index.html
declare var html2pdf: any;

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onChapterUpdate?: (chapter: ChapterContent) => void;
  selectedVoice?: string;
  onVoiceChange?: (voice: string) => void;
  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache to prevent re-fetching
const audioCache = new Map<string, AudioBuffer>();

// Helpers for Gemini Audio (PCM)
function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  // CRITICAL IOS FIX: Int16Array requires 2-byte alignment.
  let bufferToUse = data.buffer;
  let byteOffset = data.byteOffset;
  let byteLength = data.byteLength;

  if (byteLength % 2 !== 0) {
      const newBuffer = new Uint8Array(byteLength - 1);
      newBuffer.set(data.subarray(0, byteLength - 1));
      bufferToUse = newBuffer.buffer;
      byteOffset = 0;
      byteLength = newBuffer.byteLength;
  }

  const dataInt16 = new Int16Array(bufferToUse, byteOffset, byteLength / 2);
  const frameCount = dataInt16.length / numChannels;

  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [isChapterImageGenerating, setIsChapterImageGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);

  // PDF Preview State
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChapterIndex]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) {
      stopAudio();
      return;
    }

    if (!currentChapter?.content) return;

    let ctx = audioContextRef.current;

    try {
      if (!ctx) {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        if (!AudioContextClass) {
           showNotification("Audio not supported on this device", 'error');
           return;
        }
        ctx = new AudioContextClass();
        audioContextRef.current = ctx;
      }

      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      const silentBuffer = ctx.createBuffer(1, 1, 24000); 
      const silentSource = ctx.createBufferSource();
      silentSource.buffer = silentBuffer;
      silentSource.connect(ctx.destination);
      silentSource.start(0);

    } catch (e) {
      console.error("Audio unlock failed", e);
      showNotification("Could not initialize audio hardware.", 'error');
      return;
    }

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);

    try {
      const textToSpeak = currentChapter.content.slice(0, 4000);
      const pcmBase64 = await generateSpeech(textToSpeak, selectedVoice || 'Kore');

      if (!pcmBase64) throw new Error("No audio returned from API");

      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, ctx, 24000);

      audioCache.set(cacheKey, audioBuffer);

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error("Audio playback failed", err);
      showNotification("Audio generation failed: " + (err.message || "Network error"), 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;

    if (audioSourceRef.current) {
        try { audioSourceRef.current.stop(); } catch(e) {}
    }

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);

    source.onended = () => {
        setIsPlaying(false);
        audioSourceRef.current = null;
    };

    audioSourceRef.current = source;
    source.start(0);
    setIsPlaying(true);
  };

  // --- REWRITTEN PDF GENERATION LOGIC ---
  const handleDownloadPDF = async () => {
    // We target the HIDDEN container that is always in the DOM, not the preview modal
    const sourceElement = document.getElementById('print-export-container');

    if (!sourceElement) {
        showNotification("Export container not found.", 'error');
        return;
    }

    setIsGeneratingPDF(true);

    try {
        // Wait for images to be "ready" in the DOM
        await new Promise(r => setTimeout(r, 1000));

        const safeFilename = outline.title.replace(/[^a-z0-9]/gi, '_').toLowerCase() || 'ebook';

        const opt = {
          margin:       [15, 15, 15, 15], // mm
          filename:     `${safeFilename}.pdf`,
          image:        { type: 'jpeg', quality: 0.98 },
          html2canvas:  { 
              scale: 2, 
              useCORS: true, 
              logging: false,
              letterRendering: true,
              // Fixed width ensures consistency regardless of the user's screen size
              windowWidth: 800, 
              width: 800
          },
          jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait' },
          pagebreak:    { mode: ['avoid-all', 'css', 'legacy'] }
        };

        await html2pdf().set(opt).from(sourceElement).save();
        showNotification("PDF Downloaded successfully!");

    } catch (e: any) {
        console.error("PDF Generation Error:", e);
        showNotification("Failed to generate PDF.", 'error');
    } finally {
        setIsGeneratingPDF(false);
    }
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);

    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) {
      setIsExportingDocs(false);
      return;
    }

    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      console.error(e);
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => {
    if (!currentChapter) return;
    setEditContent(currentChapter.content);
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (!currentChapter || !onChapterUpdate) return;
    onChapterUpdate({
      ...currentChapter,
      content: editContent
    });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setPolishInstruction('');
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
      showNotification("Text refined!");
    } catch (e) {
      console.error(e);
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `Create a flat 2D front cover design for a book titled "${outline.title}". 
      Description: ${outline.description}. 
      Style: Minimalist, modern, striking typography, best-selling aesthetic.
      IMPORTANT: This must be a flat, rectangular 2D image suitable for printing. Do NOT render a 3D book object, do NOT show a book spine, and do NOT place the book on a table or background surface. Just the artwork itself.`;

      const base64Image = await generateImage(prompt, '3:4');
      onUpdateOutline({
        ...outline,
        coverImage: base64Image
      });
      showNotification("Cover updated!");
    } catch (e) {
      console.error(e);
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleGenerateChapterImage = async () => {
    if (!currentChapter || !onChapterUpdate) return;

    // Find summary from outline
    const chapterOutline = outline.chapters.find(c => c.chapterNumber === currentChapter.chapterNumber);
    const context = chapterOutline?.summary || currentChapter.content.slice(0, 800);

    setIsChapterImageGenerating(true);
    try {
      const prompt = `Create a raw, expressive BLACK AND WHITE PENCIL SKETCH for a book chapter.

      Story Context: "${context}"

      Style Guidelines:
      - Medium: Graphite pencil on textured paper.
      - Style: Hand-drawn, rough sketching lines, high contrast, dramatic shading. 
      - NO COLORS. Pure black, white, and greys.
      - Mood: Evocative and artistic.

      Subject:
      - Accurately depict the characters and setting described in the context.`;

      const base64 = await generateImage(prompt, '16:9');
      onChapterUpdate({
        ...currentChapter,
        image: base64
      });
      showNotification("Chapter illustration created!");
    } catch (e) {
      console.error(e);
      showNotification("Failed to generate illustration.", 'error');
    } finally {
      setIsChapterImageGenerating(false);
    }
  };

  const handleChapterSelect = (idx: number) => {
    setCurrentChapterIndex(idx);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  };

  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      {/* --- HIDDEN PDF SOURCE CONTAINER --- */}
      {/* This is positioned off-screen but has fixed dimensions so html2canvas sees it correctly */}
      <div 
        style={{
          position: 'absolute',
          top: 0,
          left: '-10000px',
          width: '800px', // A4-ish width for calculation
          zIndex: -50,
          visibility: 'visible', // Must be visible for canvas to capture
          background: '#ffffff'
        }}
      >
        <div id="print-export-container" className="bg-white text-black p-12 min-h-[1000px]">
           {/* Styles specifically for the PDF generation */}
           <style>{`
             .pdf-title-page { min-height: 900px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; page-break-after: always; }
             .pdf-chapter { page-break-before: always; margin-top: 40px; }
             .pdf-content p { margin-bottom: 1em; line-height: 1.8; text-align: justify; font-family: 'Times New Roman', serif; font-size: 14pt; }
             .pdf-content h1, .pdf-content h2 { font-family: 'Helvetica', sans-serif; color: #000; margin-bottom: 20px; }
           `}</style>

           {/* Title Page */}
           <div className="pdf-title-page">
              <h1 style={{fontSize: '48px', fontWeight: 'bold', marginBottom: '20px', textTransform: 'uppercase'}}>{outline.title}</h1>
              {outline.coverImage && (
                <img src={`data:image/jpeg;base64,${outline.coverImage}`} style={{width: '300px', height: 'auto', marginBottom: '40px', border: '1px solid #ddd'}} alt="Cover" />
              )}
              <p style={{fontSize: '18px', fontStyle: 'italic', maxWidth: '600px'}}>{outline.description}</p>
              <div style={{marginTop: 'auto', fontSize: '12px', color: '#666', textTransform: 'uppercase'}}>Generated with Lore</div>
           </div>

           {/* Chapters */}
           {chapters.map((chap) => (
             <div key={chap.chapterNumber} className="pdf-chapter">
                <div style={{textAlign: 'center', marginBottom: '40px'}}>
                   <div style={{fontSize: '14px', textTransform: 'uppercase', letterSpacing: '2px', marginBottom: '10px'}}>Chapter {chap.chapterNumber}</div>
                   <h2 style={{fontSize: '32px', fontWeight: 'bold'}}>{chap.title}</h2>
                </div>

                {chap.image && (
                  <div style={{display: 'flex', justifyContent: 'center', marginBottom: '30px'}}>
                     <img src={`data:image/jpeg;base64,${chap.image}`} style={{maxWidth: '100%', maxHeight: '300px', borderRadius: '4px'}} alt="Chapter Art"/>
                  </div>
                )}

                <div className="pdf-content">
                   <ReactMarkdown>{chap.content}</ReactMarkdown>
                </div>
             </div>
           ))}
        </div>
      </div>

      {/* --- PDF Preview Overlay --- */}
      {isPreviewOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-900/50 backdrop-blur-sm overflow-y-auto animate-in fade-in duration-200">
          <div className="min-h-screen flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-5xl rounded-xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">

                {/* Toolbar */}
                <div className="bg-slate-900 text-white p-4 flex justify-between items-center shrink-0">
                  <div className="flex items-center gap-4">
                      <button 
                        onClick={() => !isGeneratingPDF && setIsPreviewOpen(false)} 
                        disabled={isGeneratingPDF}
                        className="flex items-center gap-2 text-sm font-bold text-slate-300 hover:text-white disabled:opacity-50 transition-colors"
                      >
                        <ChevronLeft size={16} /> Back to Editor
                      </button>
                      <div className="h-4 w-px bg-slate-700"></div>
                      <span className="font-serif font-bold truncate max-w-xs">{outline.title} (PDF Preview)</span>
                  </div>
                  <button 
                    onClick={handleDownloadPDF}
                    disabled={isGeneratingPDF}
                    className={`bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-md font-bold text-sm flex items-center gap-2 shadow-sm transition-all ${isGeneratingPDF ? 'opacity-80 cursor-wait' : ''}`}
                  >
                    {isGeneratingPDF ? <Loader2 size={16} className="animate-spin" /> : <Download size={16} />}
                    {isGeneratingPDF ? 'Generating PDF...' : 'Download PDF'}
                  </button>
                </div>

                {/* Visual Preview Area (Uses standard HTML/Tailwind for screen viewing) */}
                <div className="flex-1 overflow-y-auto bg-slate-100 p-8">
                   <div className="max-w-[210mm] mx-auto bg-white shadow-xl min-h-[297mm] p-[20mm] text-black">
                      <div className="flex flex-col items-center justify-center min-h-[900px] text-center mb-12">
                          <h1 className="text-4xl md:text-5xl font-bold mb-6 uppercase tracking-wider">{outline.title}</h1>
                          <div className="w-16 h-1 bg-black mb-8"></div>
                          {outline.coverImage && (
                            <img src={`data:image/jpeg;base64,${outline.coverImage}`} className="w-64 h-auto aspect-[3/4] object-cover shadow-lg mb-12 border border-slate-200" style={{maxWidth: '100%'}} alt="Cover" />
                          )}
                          <p className="max-w-md text-gray-600 italic leading-relaxed mb-8">{outline.description}</p>
                      </div>
                      {chapters.map((chapter) => (
                        <div key={chapter.chapterNumber} className="mb-24 border-t border-gray-100 pt-12">
                            <div className="text-center mb-8">
                              <span className="text-xs font-bold uppercase tracking-widest border-b border-gray-300 pb-1 mb-4 inline-block">Chapter {chapter.chapterNumber}</span>
                              <h2 className="text-2xl font-bold mb-4">{chapter.title}</h2>
                            </div>
                            {chapter.image && (
                              <div className="mb-8 flex justify-center">
                                 <img src={`data:image/jpeg;base64,${chapter.image}`} className="max-w-full h-auto rounded-sm" style={{ maxHeight: '300px' }} alt="Chapter Art"/>
                              </div>
                            )}
                            <div className="prose prose-slate max-w-none text-justify font-serif text-sm md:text-base leading-loose">
                              <ReactMarkdown>{chapter.content}</ReactMarkdown>
                            </div>
                        </div>
                      ))}
                   </div>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* --- Main Editor (Hidden when previewing) --- */}
      <div className={`flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden ${isPreviewOpen ? 'hidden' : ''}`}>

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600">
               <X size={24} />
             </button>
          </div>

          {/* Unified Scrollable Area: Holds both chapters and controls */}
          <div className="flex-1 overflow-y-auto">
             <div className="p-4 space-y-2">
               {chapters.map((chap, idx) => (
                 <button
                   key={chap.chapterNumber}
                   onClick={() => handleChapterSelect(idx)}
                   className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                     currentChapterIndex === idx 
                     ? 'bg-blue-50 border-blue-200 text-blue-800 font-bold shadow-sm' 
                     : 'border-transparent hover:bg-slate-50 text-slate-600'
                   }`}
                 >
                   <div className="flex justify-between items-center mb-1">
                      <span className="text-xs opacity-70 uppercase tracking-wide">Chapter {chap.chapterNumber}</span>
                      {chap.isGenerating && <Loader2 size={12} className="animate-spin text-blue-500"/>}
                   </div>
                   <div className="truncate">{chap.title}</div>
                 </button>
               ))}
             </div>

             <div className="p-4 border-t border-slate-100 bg-slate-50/50 space-y-3">
                <div className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                   <div className="flex items-center gap-2 mb-2 text-xs font-bold text-slate-400 uppercase tracking-wider">
                     <Headphones size={12} /> Audiobook
                   </div>
                   <select 
                      value={selectedVoice}
                      onChange={(e) => onVoiceChange && onVoiceChange(e.target.value)}
                      className="w-full text-sm p-2 bg-slate-50 border border-slate-200 rounded mb-2 outline-none focus:border-blue-300"
                   >
                     <option value="Kore">Kore (Balanced)</option>
                     <option value="Puck">Puck (Energetic)</option>
                     <option value="Fenrir">Fenrir (Deep)</option>
                     <option value="Charon">Charon (Calm)</option>
                   </select>
                   <button 
                     onClick={playChapterAudio}
                     disabled={audioLoading || !currentChapter || currentChapter.isGenerating}
                     className={`w-full py-2 rounded-md font-bold text-sm text-white flex items-center justify-center gap-2 transition-all ${isPlaying ? 'bg-slate-800 hover:bg-slate-900' : 'bg-blue-600 hover:bg-blue-500 shadow-sm'}`}
                   >
                     {audioLoading ? <Loader2 size={14} className="animate-spin" /> : isPlaying ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                     {isPlaying ? 'Stop Reading' : audioLoading ? 'Loading Audio...' : 'Read Chapter'}
                   </button>
                </div>

                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                   <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Design & Export</div>

                   <div className="mb-4">
                     {outline.coverImage ? (
                       <div className="relative group rounded-md overflow-hidden mb-2 border border-slate-100 shadow-sm">
                          <img src={`data:image/jpeg;base64,${outline.coverImage}`} alt="Cover" className="w-full h-auto aspect-[3/4] object-cover" />
                          <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                             <button onClick={handleGenerateCover} className="text-white text-xs font-bold flex items-center gap-1 hover:underline">
                                <ImageIcon size={12} /> Regenerate
                             </button>
                          </div>
                       </div>
                     ) : (
                       <button 
                         onClick={handleGenerateCover}
                         disabled={isCoverGenerating}
                         className="w-full py-2 px-3 bg-purple-50 hover:bg-purple-100 text-purple-700 rounded-md text-xs font-bold flex items-center justify-center gap-2 transition-all mb-2"
                       >
                         {isCoverGenerating ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                         Generate Full Cover
                       </button>
                     )}
                   </div>

                   <button 
                     onClick={() => setIsPreviewOpen(true)}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors mb-1"
                   >
                     <Download size={16} />
                     PDF Preview & Download
                   </button>
                   <button 
                     onClick={handleExportDocs}
                     disabled={isExportingDocs}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors"
                   >
                     {isExportingDocs ? <Loader2 size={16} className="animate-spin" /> : <FileText size={16} />}
                     Export to Docs
                   </button>
                </div>
             </div>
          </div>

        </div>

        {/* Reader Content */}
        <div className="flex-1 flex flex-col h-full overflow-hidden bg-slate-50 relative w-full">

           <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 shrink-0 justify-between">
              <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                 <Menu size={24} />
              </button>
              <span className="font-serif font-bold text-slate-900 truncate max-w-[200px]">
                 {currentChapter ? `Ch ${currentChapter.chapterNumber}: ${currentChapter.title}` : 'Reader'}
              </span>
              <div className="w-8"></div>
           </div>

           <div className="hidden md:block absolute top-4 left-4 z-20">
              <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 bg-white shadow-md rounded-lg border border-slate-200 text-slate-600 hover:text-blue-600 transition-colors">
                 {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
              </button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-12 scroll-smooth">
             <div className="max-w-3xl mx-auto bg-white shadow-xl shadow-slate-200/50 min-h-[80vh] p-6 md:p-16 rounded-xl relative border border-slate-100">

                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-100 via-blue-50 to-blue-100 opacity-50"></div>

                {!currentChapter ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                    <Loader2 size={40} className="animate-spin mb-4 text-blue-200" />
                    <p>Loading Manuscript...</p>
                  </div>
                ) : (
                  <>
                    <div className="mb-6 pb-6 border-b border-slate-100">
                       <span className="text-xs font-bold tracking-[0.2em] text-slate-400 uppercase mb-2 block text-center">Chapter {currentChapter.chapterNumber}</span>
                       <h2 className="text-2xl md:text-4xl font-serif font-bold text-slate-900 text-center leading-tight">{currentChapter.title}</h2>
                    </div>

                    {/* Chapter Sketch UI */}
                    <div className="mb-8">
                       {currentChapter.image ? (
                         <div className="relative group mx-auto max-w-lg">
                           <img 
                             src={`data:image/jpeg;base64,${currentChapter.image}`} 
                             className="w-full h-auto rounded-lg shadow-md border border-slate-100" 
                             alt="Chapter Sketch" 
                           />
                           <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center rounded-lg">
                              <button 
                                onClick={handleGenerateChapterImage} 
                                disabled={isChapterImageGenerating}
                                className="bg-white text-slate-900 px-4 py-2 rounded-full font-bold text-sm hover:bg-blue-50 transition-colors flex items-center gap-2"
                              >
                                {isChapterImageGenerating ? <Loader2 size={14} className="animate-spin" /> : <Palette size={14} />}
                                Regenerate Sketch
                              </button>
                           </div>
                         </div>
                       ) : (
                         <div className="flex justify-center">
                            <button 
                              onClick={handleGenerateChapterImage} 
                              disabled={isChapterImageGenerating || currentChapter.isGenerating}
                              className="text-slate-400 hover:text-blue-600 hover:bg-blue-50 px-4 py-2 rounded-full text-xs font-bold uppercase tracking-wider flex items-center gap-2 transition-all border border-transparent hover:border-blue-100"
                            >
                               {isChapterImageGenerating ? <Loader2 size={14} className="animate-spin" /> : <Palette size={14} />}
                               Generate Chapter Illustration
                            </button>
                         </div>
                       )}
                    </div>

                    {isEditing ? (
                       <div className="animate-in fade-in">
                          <textarea 
                             value={editContent}
                             onChange={(e) => setEditContent(e.target.value)}
                             className="w-full h-[60vh] p-4 font-serif text-lg leading-relaxed text-slate-800 border-2 border-blue-100 rounded-lg outline-none focus:ring-2 focus:ring-blue-200 resize-y mb-4"
                          />

                          <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-6 flex gap-3 items-center">
                             <div className="bg-blue-200 p-2 rounded-full text-blue-700"><Wand2 size={16} /></div>
                             <div className="flex-1">
                                <input 
                                  value={polishInstruction}
                                  onChange={(e) => setPolishInstruction(e.target.value)}
                                  placeholder="Ask AI to polish (e.g., 'Make it more dramatic')"
                                  className="w-full bg-white border border-blue-200 rounded px-3 py-2 text-sm outline-none focus:border-blue-400"
                                  onKeyDown={(e) => e.key === 'Enter' && handlePolish()}
                                />
                             </div>
                             <button 
                               onClick={handlePolish}
                               disabled={isPolishing || !polishInstruction.trim()}
                               className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-bold rounded-lg transition-colors disabled:opacity-50"
                             >
                               {isPolishing ? <Loader2 size={16} className="animate-spin" /> : 'Refine'}
                             </button>
                          </div>

                          <div className="flex justify-end gap-3 sticky bottom-0 bg-white pt-4 border-t border-slate-100">
                             <button onClick={cancelEditing} className="px-5 py-2.5 text-slate-600 font-bold text-sm hover:bg-slate-100 rounded-lg">Cancel</button>
                             <button onClick={saveEditing} className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-sm rounded-lg shadow-lg shadow-emerald-200 flex items-center gap-2">
                                <Save size={16} /> Save Changes
                             </button>
                          </div>
                       </div>
                    ) : (
                      <div className="prose prose-lg prose-slate font-serif max-w-none prose-headings:font-sans prose-headings:font-bold prose-p:leading-loose text-slate-800">
                         {currentChapter.isGenerating ? (
                           <div className="space-y-4 animate-pulse">
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="h-4 bg-slate-100 rounded w-11/12"></div>
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="py-8 text-center text-slate-400 text-sm font-sans flex items-center justify-center gap-2">
                                <Loader2 size={16} className="animate-spin" /> Writing in progress...
                              </div>
                           </div>
                         ) : (
                           <div className="relative group min-h-[200px]">
                              <ReactMarkdown>{currentChapter.content}</ReactMarkdown>
                              <button 
                                onClick={startEditing}
                                className="absolute top-0 right-0 p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                                title="Edit Text"
                              >
                                <PenLine size={20} />
                              </button>
                           </div>
                         )}
                      </div>
                    )}
                  </>
                )}
             </div>

             <div className="max-w-3xl mx-auto mt-8 flex justify-between items-center text-sm font-medium text-slate-500 pb-24 md:pb-12 px-4">
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.max(0, prev - 1))}
                  disabled={currentChapterIndex === 0}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  <ChevronLeft size={16} /> Previous
                </button>
                <span>{currentChapterIndex + 1} / {chapters.length}</span>
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.min(chapters.length - 1, prev + 1))}
                  disabled={currentChapterIndex === chapters.length - 1}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  Next <ChevronRight size={16} />
                </button>
             </div>
           </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, Download, PenLine, Save, Headphones, Play, Square, FileText, Image as ImageIcon, Wand2, Menu, X, Sparkles, Palette } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { generateSpeech, generateImage, refineChapterText } from '../services/gemini';
import { Notification } from './Notification';

// Declare html2pdf globally as it's loaded via CDN in index.html
declare var html2pdf: any;

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onChapterUpdate?: (chapter: ChapterContent) => void;
  selectedVoice?: string;
  onVoiceChange?: (voice: string) => void;
  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache
const audioCache = new Map<string, AudioBuffer>();

function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  let bufferToUse = data.buffer;
  let byteOffset = data.byteOffset;
  let byteLength = data.byteLength;

  if (byteLength % 2 !== 0) {
      const newBuffer = new Uint8Array(byteLength - 1);
      newBuffer.set(data.subarray(0, byteLength - 1));
      bufferToUse = newBuffer.buffer;
      byteOffset = 0;
      byteLength = newBuffer.byteLength;
  }

  const dataInt16 = new Int16Array(bufferToUse, byteOffset, byteLength / 2);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [isChapterImageGenerating, setIsChapterImageGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);
  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
  }, [currentChapterIndex]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) { stopAudio(); return; }
    if (!currentChapter?.content) return;

    let ctx = audioContextRef.current;
    if (!ctx) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      ctx = new AudioContextClass();
      audioContextRef.current = ctx;
    }

    if (ctx.state === 'suspended') await ctx.resume();

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);
    try {
      const textToSpeak = currentChapter.content.slice(0, 4000);
      const pcmBase64 = await generateSpeech(textToSpeak, selectedVoice || 'Kore');
      if (!pcmBase64) throw new Error("Audio generation failed");
      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, ctx, 24000);
      audioCache.set(cacheKey, audioBuffer);
      playBuffer(audioBuffer);
    } catch (err: any) {
      showNotification(err.message || "Audio playback failed", 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    if (audioSourceRef.current) try { audioSourceRef.current.stop(); } catch(e) {}
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => { setIsPlaying(false); audioSourceRef.current = null; };
    audioSourceRef.current = source;
    source.start(0);
    setIsPlaying(true);
  };

  const handleDownloadPDF = async () => {
    const element = document.getElementById('pdf-render-root');
    if (!element) {
      showNotification("PDF source not found", 'error');
      return;
    }

    setIsGeneratingPDF(true);

    // Give browser a moment to ensure all off-screen content is rendered
    await new Promise(resolve => setTimeout(resolve, 800));

    const opt = {
      margin: [10, 10, 10, 10],
      filename: `${outline.title.replace(/\s+/g, '_')}_Manuscript.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        letterRendering: true,
        width: 800, // Fixed width for consistent capture
        windowWidth: 800,
        scrollX: 0,
        scrollY: 0
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    };

    try {
      await html2pdf().from(element).set(opt).save();
      showNotification("PDF downloaded successfully!");
      setIsPreviewOpen(false);
    } catch (err: any) {
      console.error(err);
      showNotification("Failed to generate PDF", 'error');
    } finally {
      setIsGeneratingPDF(false);
    }
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);
    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) { setIsExportingDocs(false); return; }
    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => { setEditContent(currentChapter.content); setIsEditing(true); };
  const saveEditing = () => {
    if (onChapterUpdate) onChapterUpdate({ ...currentChapter, content: editContent });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
    } catch (e) {
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `A professional, best-selling book cover for "${outline.title}". ${outline.description}. High quality, minimal, stunning. 2D flat artwork ONLY.`;
      const base64 = await generateImage(prompt, '3:4');
      onUpdateOutline({ ...outline, coverImage: base64 });
      showNotification("Cover updated!");
    } catch (e) {
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleGenerateChapterImage = async () => {
    if (!currentChapter || !onChapterUpdate) return;
    setIsChapterImageGenerating(true);
    try {
      const prompt = `A detailed charcoal pencil sketch for a book illustration. Scene: ${currentChapter.title}. Description: ${currentChapter.content.slice(0, 300)}. Black and white, artistic, evocative.`;
      const base64 = await generateImage(prompt, '16:9');
      onChapterUpdate({ ...currentChapter, image: base64 });
    } catch (e) {
      showNotification("Failed to generate sketch.", 'error');
    } finally {
      setIsChapterImageGenerating(false);
    }
  };

  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      {/* --- HIDDEN PDF RENDER ROOT --- 
          Crucially, we don't use display:none. We move it off screen.
      */}
      <div 
        id="pdf-render-root" 
        style={{ 
          position: 'absolute', 
          left: '-10000px', 
          top: 0, 
          width: '800px', 
          background: '#fff', 
          color: '#000',
          padding: '40px',
          boxSizing: 'border-box'
        }}
      >
        <style>{`
          .pdf-page { font-family: 'Times New Roman', serif; line-height: 1.6; }
          .pdf-title-page { height: 1000px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; page-break-after: always; }
          .pdf-chapter { page-break-before: always; margin-top: 40px; }
          .pdf-chapter-title { font-size: 28pt; font-weight: bold; margin-bottom: 20pt; }
          .pdf-content p { font-size: 12pt; margin-bottom: 12pt; text-align: justify; }
          .pdf-image { max-width: 100%; height: auto; margin: 20px 0; border-radius: 4px; }
        `}</style>

        <div className="pdf-title-page">
          <h1 style={{ fontSize: '48pt', margin: '0 0 20pt 0' }}>{outline.title}</h1>
          {outline.coverImage && (
            <img src={`data:image/jpeg;base64,${outline.coverImage}`} style={{ width: '300px', marginBottom: '40pt' }} />
          )}
          <p style={{ fontSize: '16pt', maxWidth: '600px', fontStyle: 'italic' }}>{outline.description}</p>
        </div>

        {chapters.map((chap) => (
          <div key={chap.chapterNumber} className="pdf-chapter">
            <h2 className="pdf-chapter-title">Chapter {chap.chapterNumber}: {chap.title}</h2>
            {chap.image && (
              <img src={`data:image/jpeg;base64,${chap.image}`} className="pdf-image" />
            )}
            <div className="pdf-content">
              <ReactMarkdown>{chap.content}</ReactMarkdown>
            </div>
          </div>
        ))}
      </div>

      {/* --- Main UI --- */}
      <div className="flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden">

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div>
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-400 uppercase tracking-widest font-bold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600"><X size={24} /></button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-2">
            {chapters.map((chap, idx) => (
              <button
                key={chap.chapterNumber}
                onClick={() => { setCurrentChapterIndex(idx); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
                className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                  currentChapterIndex === idx ? 'bg-blue-50 border-blue-200 text-blue-800 font-bold' : 'border-transparent hover:bg-slate-50 text-slate-600'
                }`}
              >
                <div className="flex justify-between items-center mb-1">
                   <span className="text-[10px] opacity-60 uppercase">Chapter {chap.chapterNumber}</span>
                   {chap.isGenerating && <Loader2 size={10} className="animate-spin text-blue-400"/>}
                </div>
                <div className="truncate">{chap.title}</div>
              </button>
            ))}
          </div>

          <div className="p-4 border-t border-slate-100 bg-slate-50 space-y-3">
             <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm">
                <div className="flex items-center justify-between mb-3">
                   <div className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1"><Headphones size={12}/> Audiobook</div>
                   <select 
                     value={selectedVoice} 
                     onChange={(e) => onVoiceChange?.(e.target.value)}
                     className="text-[10px] bg-slate-100 border-0 rounded px-1 py-0.5 outline-none font-bold"
                   >
                     <option value="Kore">Kore</option><option value="Puck">Puck</option><option value="Fenrir">Fenrir</option>
                   </select>
                </div>
                <button 
                  onClick={playChapterAudio}
                  disabled={audioLoading}
                  className={`w-full py-2.5 rounded-lg font-bold text-xs flex items-center justify-center gap-2 transition-all ${isPlaying ? 'bg-slate-800 text-white' : 'bg-blue-600 text-white shadow-lg shadow-blue-100'}`}
                >
                  {audioLoading ? <Loader2 size={14} className="animate-spin" /> : isPlaying ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                  {isPlaying ? 'Stop' : 'Read Chapter'}
                </button>
             </div>

             <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm">
                <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Publishing</div>
                <div className="grid grid-cols-2 gap-2">
                   <button 
                     onClick={handleDownloadPDF} 
                     disabled={isGeneratingPDF}
                     className="bg-slate-50 hover:bg-slate-100 p-2 rounded-lg text-slate-600 text-xs font-bold flex flex-col items-center gap-1 transition-all"
                   >
                     {isGeneratingPDF ? <Loader2 size={14} className="animate-spin" /> : <Download size={14} />}
                     PDF
                   </button>
                   <button 
                     onClick={handleExportDocs} 
                     className="bg-slate-50 hover:bg-slate-100 p-2 rounded-lg text-slate-600 text-xs font-bold flex flex-col items-center gap-1 transition-all"
                   >
                     <FileText size={14} />
                     Docs
                   </button>
                </div>
             </div>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 flex flex-col h-full bg-slate-50 relative">
           <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 shrink-0">
              <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600"><Menu size={24} /></button>
              <h2 className="flex-1 text-center font-serif font-bold truncate px-4">{currentChapter?.title || 'Reader'}</h2>
              <div className="w-10"></div>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-12">
             <div className="max-w-3xl mx-auto bg-white shadow-xl shadow-slate-200/50 min-h-[80vh] p-8 md:p-16 rounded-2xl relative border border-slate-100">
                {!currentChapter ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-300">
                    <Loader2 size={40} className="animate-spin mb-4" /><p>Loading Manuscript...</p>
                  </div>
                ) : (
                  <>
                    <div className="text-center mb-10 pb-10 border-b border-slate-100">
                       <span className="text-[10px] font-bold tracking-[0.3em] text-slate-400 uppercase mb-3 block">Chapter {currentChapter.chapterNumber}</span>
                       <h2 className="text-3xl md:text-5xl font-serif font-bold text-slate-900 leading-tight">{currentChapter.title}</h2>
                    </div>

                    <div className="mb-10">
                       {currentChapter.image ? (
                         <div className="relative group rounded-xl overflow-hidden shadow-lg border border-slate-100 max-w-lg mx-auto">
                           <img src={`data:image/jpeg;base64,${currentChapter.image}`} className="w-full h-auto" />
                           <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                              <button onClick={handleGenerateChapterImage} disabled={isChapterImageGenerating} className="bg-white px-4 py-2 rounded-full font-bold text-xs flex items-center gap-2">
                                {isChapterImageGenerating ? <Loader2 size={14} className="animate-spin" /> : <Palette size={14} />} Regenerate
                              </button>
                           </div>
                         </div>
                       ) : (
                         <div className="text-center">
                            <button onClick={handleGenerateChapterImage} disabled={isChapterImageGenerating || currentChapter.isGenerating} className="text-slate-400 hover:text-blue-600 text-[10px] font-bold uppercase tracking-widest flex items-center gap-2 mx-auto px-4 py-2 border border-dashed border-slate-200 rounded-lg hover:border-blue-200 transition-all">
                               {isChapterImageGenerating ? <Loader2 size={12} className="animate-spin" /> : <Palette size={12} />} Create Illustration
                            </button>
                         </div>
                       )}
                    </div>

                    {isEditing ? (
                       <div className="space-y-4">
                          <textarea 
                             value={editContent} onChange={(e) => setEditContent(e.target.value)}
                             className="w-full h-[60vh] p-6 font-serif text-lg leading-relaxed text-slate-800 bg-slate-50 border-0 rounded-xl outline-none focus:ring-2 focus:ring-blue-100 resize-none"
                          />
                          <div className="bg-blue-50 p-4 rounded-xl flex gap-3 items-center border border-blue-100">
                             <Wand2 size={18} className="text-blue-500" />
                             <input 
                               value={polishInstruction} onChange={(e) => setPolishInstruction(e.target.value)}
                               placeholder="Instruction to AI (e.g. 'Make it more tense')"
                               className="flex-1 bg-transparent border-0 outline-none text-sm placeholder:text-blue-300"
                               onKeyDown={(e) => e.key === 'Enter' && handlePolish()}
                             />
                             <button onClick={handlePolish} disabled={isPolishing || !polishInstruction.trim()} className="px-4 py-2 bg-blue-600 text-white text-xs font-bold rounded-lg disabled:opacity-50">
                               {isPolishing ? <Loader2 size={14} className="animate-spin" /> : 'Refine'}
                             </button>
                          </div>
                          <div className="flex justify-end gap-3 pt-4 border-t">
                             <button onClick={() => setIsEditing(false)} className="px-6 py-2.5 text-slate-500 font-bold text-sm">Cancel</button>
                             <button onClick={saveEditing} className="px-6 py-2.5 bg-emerald-600 text-white font-bold text-sm rounded-xl shadow-lg shadow-emerald-100 flex items-center gap-2"><Save size={16} /> Save</button>
                          </div>
                       </div>
                    ) : (
                      <div className="prose prose-slate prose-lg max-w-none font-serif text-slate-800 leading-loose text-justify relative group min-h-[400px]">
                         {currentChapter.isGenerating ? (
                           <div className="space-y-4 py-8"><div className="h-4 bg-slate-100 rounded w-full animate-pulse"></div><div className="h-4 bg-slate-100 rounded w-5/6 animate-pulse"></div><div className="h-4 bg-slate-100 rounded w-full animate-pulse"></div><p className="text-center text-slate-300 text-xs italic mt-8">Gemini is drafting this chapter...</p></div>
                         ) : (
                           <>
                             <ReactMarkdown>{currentChapter.content}</ReactMarkdown>
                             <button onClick={startEditing} className="absolute top-0 right-0 p-2 text-slate-300 hover:text-blue-600 opacity-0 group-hover:opacity-100 transition-all"><PenLine size={20} /></button>
                           </>
                         )}
                      </div>
                    )}
                  </>
                )}
             </div>

             <div className="max-w-3xl mx-auto mt-8 flex justify-between items-center text-xs font-bold text-slate-400 uppercase tracking-widest px-4 pb-12">
                <button onClick={() => setCurrentChapterIndex(p => Math.max(0, p-1))} disabled={currentChapterIndex === 0} className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-20 transition-colors"><ChevronLeft size={16}/> Prev</button>
                <span>{currentChapterIndex + 1} / {chapters.length}</span>
                <button onClick={() => setCurrentChapterIndex(p => Math.min(chapters.length-1, p+1))} disabled={currentChapterIndex === chapters.length-1} className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-20 transition-colors">Next <ChevronRight size={16}/></button>
             </div>
           </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, Download, PenLine, Save, Headphones, Play, Square, FileText, Image as ImageIcon, Wand2, Menu, X, Sparkles, Palette } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { generateSpeech, generateImage, refineChapterText } from '../services/gemini';
import { Notification } from './Notification';

// Declare html2pdf globally as it's loaded via CDN in index.html
declare var html2pdf: any;

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onChapterUpdate?: (chapter: ChapterContent) => void;
  selectedVoice?: string;
  onVoiceChange?: (voice: string) => void;
  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache
const audioCache = new Map<string, AudioBuffer>();

function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  let bufferToUse = data.buffer;
  let byteOffset = data.byteOffset;
  let byteLength = data.byteLength;

  if (byteLength % 2 !== 0) {
      const newBuffer = new Uint8Array(byteLength - 1);
      newBuffer.set(data.subarray(0, byteLength - 1));
      bufferToUse = newBuffer.buffer;
      byteOffset = 0;
      byteLength = newBuffer.byteLength;
  }

  const dataInt16 = new Int16Array(bufferToUse, byteOffset, byteLength / 2);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [isChapterImageGenerating, setIsChapterImageGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);

  // PDF Generation State: We use a specific mode to render the print layout
  const [isPdfMode, setIsPdfMode] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
  }, [currentChapterIndex]);

  // --- PDF GENERATION LOGIC ---
  // This effect watches for isPdfMode. When true, it renders the overlay, waits for it to paint, then captures.
  useEffect(() => {
    if (!isPdfMode) return;

    let isMounted = true;

    const generate = async () => {
       // 1. Wait for the DOM to fully render the PDF overlay (images, fonts)
       // A 1.5s delay is safe to ensure layout stability on mobile devices.
       await new Promise(r => setTimeout(r, 1500));

       if (!isMounted) return;

       const element = document.getElementById('pdf-root');
       if (!element) {
          showNotification("Could not find PDF content.", 'error');
          setIsPdfMode(false);
          return;
       }

       // 2. Configuration for robust capture
       const opt = {
          margin: [15, 15, 15, 15], // mm
          filename: `${outline.title.replace(/[^a-z0-9]/gi, '_').substring(0, 30)}.pdf`,
          image: { type: 'jpeg', quality: 0.98 },
          html2canvas: { 
            scale: 2, 
            useCORS: true, 
            logging: false,
            // FORCE DESKTOP WIDTH: This is the magic fix for mobile blank pages.
            // It forces the engine to capture as if it were an 800px wide window.
            windowWidth: 800,
            width: 800,
            x: 0,
            y: 0,
            scrollX: 0,
            scrollY: 0
          },
          jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
          pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
       };

       try {
         await html2pdf().set(opt).from(element).save();
         showNotification("PDF Downloaded!");
       } catch(e) {
         console.error(e);
         showNotification("PDF Generation Error", 'error');
       } finally {
         if (isMounted) setIsPdfMode(false);
       }
    };

    generate();

    return () => { isMounted = false; };
  }, [isPdfMode]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) { stopAudio(); return; }
    if (!currentChapter?.content) return;

    let ctx = audioContextRef.current;
    if (!ctx) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      ctx = new AudioContextClass();
      audioContextRef.current = ctx;
    }

    if (ctx.state === 'suspended') await ctx.resume();

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);
    try {
      const textToSpeak = currentChapter.content.slice(0, 4000);
      const pcmBase64 = await generateSpeech(textToSpeak, selectedVoice || 'Kore');
      if (!pcmBase64) throw new Error("Audio generation failed");
      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, ctx, 24000);
      audioCache.set(cacheKey, audioBuffer);
      playBuffer(audioBuffer);
    } catch (err: any) {
      showNotification(err.message || "Audio playback failed", 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;
    if (audioSourceRef.current) try { audioSourceRef.current.stop(); } catch(e) {}
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => { setIsPlaying(false); audioSourceRef.current = null; };
    audioSourceRef.current = source;
    source.start(0);
    setIsPlaying(true);
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);
    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) { setIsExportingDocs(false); return; }
    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => { setEditContent(currentChapter.content); setIsEditing(true); };
  const saveEditing = () => {
    if (onChapterUpdate) onChapterUpdate({ ...currentChapter, content: editContent });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
    } catch (e) {
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `A professional book cover for "${outline.title}". ${outline.description}. Minimalist, 2D flat artwork.`;
      const base64 = await generateImage(prompt, '3:4');
      onUpdateOutline({ ...outline, coverImage: base64 });
    } catch (e) {
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleGenerateChapterImage = async () => {
    if (!currentChapter || !onChapterUpdate) return;
    setIsChapterImageGenerating(true);
    try {
      const prompt = `Charcoal sketch. ${currentChapter.title}. ${currentChapter.content.slice(0, 200)}. High contrast, black and white.`;
      const base64 = await generateImage(prompt, '16:9');
      onChapterUpdate({ ...currentChapter, image: base64 });
    } catch (e) {
      showNotification("Failed to generate sketch.", 'error');
    } finally {
      setIsChapterImageGenerating(false);
    }
  };

  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      {/* --- PDF OVERLAY (Only visible during generation) --- 
          This is the key fix. We render the PDF content on top of the app in a visible layer.
          This ensures html2canvas captures valid pixels, not blank space.
      */}
      {isPdfMode && (
        <div className="fixed inset-0 z-[9999] bg-white overflow-y-auto">
          {/* Progress Overlay for the user */}
          <div className="fixed top-0 left-0 w-full h-full bg-white/95 flex flex-col items-center justify-center z-[10000]">
             <Loader2 size={64} className="animate-spin text-blue-600 mb-6" />
             <h2 className="text-3xl font-bold text-slate-800 mb-2">Generating PDF</h2>
             <p className="text-slate-500">Rendering book layout...</p>
          </div>

          {/* The Content to Capture - Force Width to 800px for consistency */}
          <div id="pdf-root" style={{ width: '800px', margin: '0 auto', background: 'white', padding: '40px', minHeight: '100vh' }}>
             <style>{`
               .pdf-text { font-family: 'Georgia', serif; font-size: 14pt; line-height: 1.6; text-align: justify; color: #000; }
               .pdf-title-page { height: 1000px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; page-break-after: always; }
               .pdf-chapter { page-break-before: always; margin-top: 50px; }
               h1 { font-size: 48pt; margin-bottom: 20px; font-weight: bold; line-height: 1.1; color: #000; }
               h2 { font-size: 32pt; margin-bottom: 30px; font-weight: bold; color: #000; }
               p { margin-bottom: 1em; }
             `}</style>

             <div className="pdf-title-page">
                <h1>{outline.title}</h1>
                {outline.coverImage && (
                  <img src={`data:image/jpeg;base64,${outline.coverImage}`} style={{ width: '350px', height: 'auto', marginBottom: '40px', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} />
                )}
                <p style={{ fontSize: '18pt', fontStyle: 'italic', maxWidth: '600px' }}>{outline.description}</p>
             </div>

             {chapters.map((chap) => (
               <div key={chap.chapterNumber} className="pdf-chapter">
                  <div style={{textAlign: 'center', marginBottom: '40px'}}>
                     <div style={{fontSize: '14pt', textTransform: 'uppercase', letterSpacing: '2px', marginBottom: '10px'}}>Chapter {chap.chapterNumber}</div>
                     <h2>{chap.title}</h2>
                  </div>
                  {chap.image && (
                     <div style={{display: 'flex', justifyContent: 'center', marginBottom: '30px'}}>
                        <img src={`data:image/jpeg;base64,${chap.image}`} style={{ maxWidth: '100%', borderRadius: '4px' }} />
                     </div>
                  )}
                  <div className="pdf-text">
                     <ReactMarkdown>{chap.content}</ReactMarkdown>
                  </div>
               </div>
             ))}
          </div>
        </div>
      )}

      {/* --- Main UI --- */}
      <div className="flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden">

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div>
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-400 uppercase tracking-widest font-bold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600"><X size={24} /></button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-2">
            {chapters.map((chap, idx) => (
              <button
                key={chap.chapterNumber}
                onClick={() => { setCurrentChapterIndex(idx); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
                className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                  currentChapterIndex === idx ? 'bg-blue-50 border-blue-200 text-blue-800 font-bold' : 'border-transparent hover:bg-slate-50 text-slate-600'
                }`}
              >
                <div className="flex justify-between items-center mb-1">
                   <span className="text-[10px] opacity-60 uppercase">Chapter {chap.chapterNumber}</span>
                   {chap.isGenerating && <Loader2 size={10} className="animate-spin text-blue-400"/>}
                </div>
                <div className="truncate">{chap.title}</div>
              </button>
            ))}
          </div>

          <div className="p-4 border-t border-slate-100 bg-slate-50 space-y-3">
             <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm">
                <div className="flex items-center justify-between mb-3">
                   <div className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1"><Headphones size={12}/> Audiobook</div>
                   <select 
                     value={selectedVoice} 
                     onChange={(e) => onVoiceChange?.(e.target.value)}
                     className="text-[10px] bg-slate-100 border-0 rounded px-1 py-0.5 outline-none font-bold"
                   >
                     <option value="Kore">Kore</option><option value="Puck">Puck</option><option value="Fenrir">Fenrir</option>
                   </select>
                </div>
                <button 
                  onClick={playChapterAudio}
                  disabled={audioLoading}
                  className={`w-full py-2.5 rounded-lg font-bold text-xs flex items-center justify-center gap-2 transition-all ${isPlaying ? 'bg-slate-800 text-white' : 'bg-blue-600 text-white shadow-lg shadow-blue-100'}`}
                >
                  {audioLoading ? <Loader2 size={14} className="animate-spin" /> : isPlaying ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                  {isPlaying ? 'Stop' : 'Read Chapter'}
                </button>
             </div>

             <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm">
                <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Publishing</div>
                <div className="grid grid-cols-2 gap-2">
                   <button 
                     onClick={() => setIsPdfMode(true)}
                     disabled={isPdfMode}
                     className="bg-slate-50 hover:bg-slate-100 p-2 rounded-lg text-slate-600 text-xs font-bold flex flex-col items-center gap-1 transition-all"
                   >
                     {isPdfMode ? <Loader2 size={14} className="animate-spin" /> : <Download size={14} />}
                     PDF
                   </button>
                   <button 
                     onClick={handleExportDocs} 
                     className="bg-slate-50 hover:bg-slate-100 p-2 rounded-lg text-slate-600 text-xs font-bold flex flex-col items-center gap-1 transition-all"
                   >
                     <FileText size={14} />
                     Docs
                   </button>
                </div>
             </div>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 flex flex-col h-full bg-slate-50 relative">
           <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 shrink-0">
              <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600"><Menu size={24} /></button>
              <h2 className="flex-1 text-center font-serif font-bold truncate px-4">{currentChapter?.title || 'Reader'}</h2>
              <div className="w-10"></div>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-12">
             <div className="max-w-3xl mx-auto bg-white shadow-xl shadow-slate-200/50 min-h-[80vh] p-8 md:p-16 rounded-2xl relative border border-slate-100">
                {!currentChapter ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-300">
                    <Loader2 size={40} className="animate-spin mb-4" /><p>Loading Manuscript...</p>
                  </div>
                ) : (
                  <>
                    <div className="text-center mb-10 pb-10 border-b border-slate-100">
                       <span className="text-[10px] font-bold tracking-[0.3em] text-slate-400 uppercase mb-3 block">Chapter {currentChapter.chapterNumber}</span>
                       <h2 className="text-3xl md:text-5xl font-serif font-bold text-slate-900 leading-tight">{currentChapter.title}</h2>
                    </div>

                    <div className="mb-10">
                       {currentChapter.image ? (
                         <div className="relative group rounded-xl overflow-hidden shadow-lg border border-slate-100 max-w-lg mx-auto">
                           <img src={`data:image/jpeg;base64,${currentChapter.image}`} className="w-full h-auto" />
                           <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                              <button onClick={handleGenerateChapterImage} disabled={isChapterImageGenerating} className="bg-white px-4 py-2 rounded-full font-bold text-xs flex items-center gap-2">
                                {isChapterImageGenerating ? <Loader2 size={14} className="animate-spin" /> : <Palette size={14} />} Regenerate
                              </button>
                           </div>
                         </div>
                       ) : (
                         <div className="text-center">
                            <button onClick={handleGenerateChapterImage} disabled={isChapterImageGenerating || currentChapter.isGenerating} className="text-slate-400 hover:text-blue-600 text-[10px] font-bold uppercase tracking-widest flex items-center gap-2 mx-auto px-4 py-2 border border-dashed border-slate-200 rounded-lg hover:border-blue-200 transition-all">
                               {isChapterImageGenerating ? <Loader2 size={12} className="animate-spin" /> : <Palette size={12} />} Create Illustration
                            </button>
                         </div>
                       )}
                    </div>

                    {isEditing ? (
                       <div className="space-y-4">
                          <textarea 
                             value={editContent} onChange={(e) => setEditContent(e.target.value)}
                             className="w-full h-[60vh] p-6 font-serif text-lg leading-relaxed text-slate-800 bg-slate-50 border-0 rounded-xl outline-none focus:ring-2 focus:ring-blue-100 resize-none"
                          />
                          <div className="bg-blue-50 p-4 rounded-xl flex gap-3 items-center border border-blue-100">
                             <Wand2 size={18} className="text-blue-500" />
                             <input 
                               value={polishInstruction} onChange={(e) => setPolishInstruction(e.target.value)}
                               placeholder="Instruction to AI (e.g. 'Make it more tense')"
                               className="flex-1 bg-transparent border-0 outline-none text-sm placeholder:text-blue-300"
                               onKeyDown={(e) => e.key === 'Enter' && handlePolish()}
                             />
                             <button onClick={handlePolish} disabled={isPolishing || !polishInstruction.trim()} className="px-4 py-2 bg-blue-600 text-white text-xs font-bold rounded-lg disabled:opacity-50">
                               {isPolishing ? <Loader2 size={14} className="animate-spin" /> : 'Refine'}
                             </button>
                          </div>
                          <div className="flex justify-end gap-3 pt-4 border-t">
                             <button onClick={() => setIsEditing(false)} className="px-6 py-2.5 text-slate-500 font-bold text-sm">Cancel</button>
                             <button onClick={saveEditing} className="px-6 py-2.5 bg-emerald-600 text-white font-bold text-sm rounded-xl shadow-lg shadow-emerald-100 flex items-center gap-2"><Save size={16} /> Save</button>
                          </div>
                       </div>
                    ) : (
                      <div className="prose prose-slate prose-lg max-w-none font-serif text-slate-800 leading-loose text-justify relative group min-h-[400px]">
                         {currentChapter.isGenerating ? (
                           <div className="space-y-4 py-8"><div className="h-4 bg-slate-100 rounded w-full animate-pulse"></div><div className="h-4 bg-slate-100 rounded w-5/6 animate-pulse"></div><div className="h-4 bg-slate-100 rounded w-full animate-pulse"></div><p className="text-center text-slate-300 text-xs italic mt-8">Gemini is drafting this chapter...</p></div>
                         ) : (
                           <>
                             <ReactMarkdown>{currentChapter.content}</ReactMarkdown>
                             <button onClick={startEditing} className="absolute top-0 right-0 p-2 text-slate-300 hover:text-blue-600 opacity-0 group-hover:opacity-100 transition-all"><PenLine size={20} /></button>
                           </>
                         )}
                      </div>
                    )}
                  </>
                )}
             </div>

             <div className="max-w-3xl mx-auto mt-8 flex justify-between items-center text-xs font-bold text-slate-400 uppercase tracking-widest px-4 pb-12">
                <button onClick={() => setCurrentChapterIndex(p => Math.max(0, p-1))} disabled={currentChapterIndex === 0} className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-20 transition-colors"><ChevronLeft size={16}/> Prev</button>
                <span>{currentChapterIndex + 1} / {chapters.length}</span>
                <button onClick={() => setCurrentChapterIndex(p => Math.min(chapters.length-1, p+1))} disabled={currentChapterIndex === chapters.length-1} className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-20 transition-colors">Next <ChevronRight size={16}/></button>
             </div>
           </div>
        </div>
      </div>
    </>
  );
};

import { GoogleGenAI, Type, Schema, Modality } from "@google/genai";
import { BookOutline, ChapterOutline, Source, SourceType, WritingStyle } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Models
const MODEL_FAST = 'gemini-2.5-flash';
const MODEL_SMART = 'gemini-3-pro-preview';
// Upgraded to Pro Image model for high-quality covers
const MODEL_IMAGE = 'gemini-3-pro-image-preview';
const MODEL_TTS = 'gemini-2.5-flash-preview-tts';

const isFatalError = (error: any): boolean => {
  const msg = error?.message || '';
  const status = error?.status;
  // Fail fast on permission denied (leaked key, no quota, etc)
  if (status === 403 || status === 401) return true;
  if (msg.includes('leaked') || msg.includes('API key') || msg.includes('PERMISSION_DENIED')) return true;
  return false;
};

// Helper for delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export interface TrendResult {
  content: string;
  sources: { title: string; uri: string }[];
}

export const researchBookTrends = async (): Promise<TrendResult> => {
  try {
    const response = await ai.models.generateContent({
      model: MODEL_FAST, // Flash is efficient for search grounding
      contents: "Act as a publishing market analyst. Perform deep online research to identify the current top 5 trending ebook topics/genres for the current week/month. For each trend, provide: 1. The Genre/Topic Name. 2. Why it is trending (viral events, seasonal, etc). 3. Estimated gross sales potential or popularity ranking if available. 4. Target audience. 5. A specific 'Book Idea' prompt for a user. Summarize the findings in markdown.",
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const sources: { title: string; uri: string }[] = [];
    if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
      response.candidates[0].groundingMetadata.groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri && chunk.web?.title) {
          sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
    }

    return {
      content: response.text || "No trends found.",
      sources: sources
    };
  } catch (error) {
    console.error("Trend research error:", error);
    throw new Error("Failed to research trends.");
  }
};

