            <button 
                onClick={addChapter}
                className="flex items-center gap-2 text-slate-500 hover:text-blue-600 font-bold border-2 border-dashed border-slate-200 hover:border-blue-300 px-6 py-3 rounded-xl transition-all hover:bg-blue-50"
            >
