  }
};

export const generateOutline = async (sources: Source[], customInstruction?: string): Promise<BookOutline> => {
  const parts: any[] = [];

  // 1. System Instruction / Goal
  let systemText = `You are a professional book editor. Analyze the provided source materials to create a comprehensive book outline.

    The source material may include text notes, audio transcripts, and visual references (images).
    Your job is to find the narrative arc, themes, and key events to structure a cohesive non-fiction or fiction book.

    STRUCTURE REQUIREMENTS:
    1. Introduction: Include a distinct "Introduction" chapter first (assign it chapterNumber: 0). This section MUST set the context, tone, and hook the reader. It MUST NOT summarize the entire book's plot or ending.
    2. Chapter 1: Begin the actual narrative or main content here, following the Introduction.
    3. Subsequent Chapters: Develop the story/content step-by-step.

    If images are provided, incorporate their visual details (settings, characters, mood) into the descriptions and summaries.`;

  if (customInstruction && customInstruction.trim()) {
    systemText += `\n\nIMPORTANT SPECIAL INSTRUCTIONS:\nThe user has provided specific guidance for this outline: "${customInstruction}".\nYou must prioritize this request when structuring the book.`;
  }

  parts.push({ text: systemText });

  // 2. Add Sources
  for (const source of sources) {
    if (source.type === SourceType.TEXT) {
      parts.push({ text: `\n\n--- Source: ${source.name} (Notes) ---\n${source.content}` });
    } else if (source.type === SourceType.AUDIO && source.transcription) {
      parts.push({ text: `\n\n--- Source: ${source.name} (Transcript) ---\n${source.transcription}` });
    } else if (source.type === SourceType.IMAGE) {
       parts.push({ text: `\n\n--- Source: ${source.name} (Visual Reference) ---` });
       parts.push({
         inlineData: {
           data: source.content,
           mimeType: source.mimeType || 'image/jpeg'
         }
       });
    }
  }

  const schema: Schema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING, description: "A creative and engaging title for the book." },
      description: { type: Type.STRING, description: "A synopsis of the book." },
      chapters: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            chapterNumber: { type: Type.INTEGER },
            title: { type: Type.STRING },
            summary: { type: Type.STRING, description: "Detailed plot points to cover in this chapter." }
          },
          required: ["chapterNumber", "title", "summary"]
        }
      }
    },
    required: ["title", "description", "chapters"]
  };

  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: MODEL_SMART,
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      }
    });

    if (!response.text) {
        throw new Error("AI returned an empty response. Please try again or check your source material.");
    }

    // Clean up potential markdown blocks if present (though schema mode usually avoids this)
    const jsonStr = response.text.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(jsonStr) as BookOutline;
  } catch (error) {
    console.error("Outline generation error:", error);
    if (isFatalError(error)) throw error;
    throw new Error("Failed to generate outline.");
  }
};

export const generateImage = async (prompt: string, aspectRatio: "1:1" | "3:4" | "4:3" | "16:9" | "9:16" = "1:1"): Promise<string> => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: MODEL_IMAGE,
      contents: {
        parts: [
          { text: prompt }
        ]
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
          imageSize: "1K" // Required for Pro Image model
        }
      }
    });

    if (response.candidates) {
      for (const candidate of response.candidates) {
        if (candidate.content && candidate.content.parts) {
          for (const part of candidate.content.parts) {
            if (part.inlineData && part.inlineData.data) {
              return part.inlineData.data;
            }
          }
        }
      }
    }

    if (response.promptFeedback?.blockReason) {
        throw new Error(`Image generation blocked: ${response.promptFeedback.blockReason}`);
    }

    throw new Error("No image data found in response.");
  } catch (error) {
    console.error("Image generation error:", error);
    if (isFatalError(error)) throw error;
    throw new Error("Failed to generate image.");
  }
};

export const writeChapter = async (
  chapter: ChapterOutline,
  outline: BookOutline,
  sources: Source[],
  style: WritingStyle = 'standard'
): Promise<string> => {

   const parts: any[] = [];

   // Check if this is the special Introduction chapter
   const isIntro = chapter.chapterNumber === 0;
   const chapterLabel = isIntro ? "Introduction" : `Chapter ${chapter.chapterNumber}`;

   // Context Header
   let contextIntro = `You are a best-selling author. Write the full content for the ${chapterLabel}: "${chapter.title}".

   Book Title: ${outline.title}
   Book Description: ${outline.description}

   Summary/Goals for this section: ${chapter.summary}`;

   const styleInstructions: Record<string, string> = {
     'standard': 'Write in a clear, engaging, and professional manner.',
     'literary': 'Use rich descriptions, metaphors, and elevated prose.',
     'humorous': 'Be witty, light-hearted, and entertaining.',
     'technical': 'Be precise, factual, and educational.',
     'simple': 'Use simple vocabulary and direct sentence structures for high readability.',
     'sarcastic': 'Write in a highly sarcastic, witty manner with adult humor and a cynical, sharp tone. Do not be afraid to be edgy.'
   };

   contextIntro += `\n\nWriting Style: ${styleInstructions[style] || styleInstructions['standard']}

   Instructions:
   - Write in an engaging, high-quality literary style matching the requested tone.
   - Ensure continuity with the overall book theme.
   - Use the source material as the factual/narrative basis but expand creatively.
   - Format with Markdown (headers, paragraphs).
   - If images are provided in the source material, use them to vividly describe scenes, characters, or items.
   ${isIntro ? '- IMPORTANT: This is the Introduction. Focus on setting the stage, introducing the world/characters, and hooking the reader. Do NOT summarize the entire plot.' : ''}`;

   parts.push({ text: contextIntro });

   // Add Sources
   for (const source of sources) {
      if (source.type === SourceType.TEXT) {
        parts.push({ text: `\n[Source: ${source.name}]: ${source.content.slice(0, 5000)}` });
      } else if (source.type === SourceType.AUDIO && source.transcription) {
        parts.push({ text: `\n[Source: ${source.name}]: ${source.transcription.slice(0, 5000)}` });
      } else if (source.type === SourceType.IMAGE) {
        parts.push({ text: `\n[Source: ${source.name} (Image Reference)]` });
        parts.push({
          inlineData: {
             data: source.content,
             mimeType: source.mimeType || 'image/jpeg'
          }
        });
      }
   }

   const MAX_RETRIES = 5;
   let lastError;
   const ai = getAI();

   // Primary Model Attempt (Pro)
   for (let i = 0; i < MAX_RETRIES; i++) {
     try {
       const response = await ai.models.generateContent({
         model: MODEL_SMART,
         contents: { parts }
       });

       return response.text || "";
     } catch (error: any) {
        lastError = error;
        // Check for fatal errors that shouldn't be retried
        if (isFatalError(error)) {
           throw error; 
        }

        console.warn(`Smart model attempt ${i + 1} failed for chapter ${chapter.chapterNumber}:`, error.message);

        // Exponential backoff: 2s, 4s, 8s, 16s, 32s
        await delay(2000 * Math.pow(2, i));
     }
   }

   // Fallback Model Attempt (Flash) with retries
   console.warn(`All primary attempts failed. Falling back to ${MODEL_FAST} for chapter ${chapter.chapterNumber}`);

   for (let i = 0; i < MAX_RETRIES; i++) {
      try {
          const response = await ai.models.generateContent({
            model: MODEL_FAST,
            contents: { parts }
          });
          return response.text || "";
      } catch (fallbackError: any) {
          lastError = fallbackError;
          if (isFatalError(fallbackError)) throw fallbackError;

          console.warn(`Fallback model attempt ${i + 1} failed:`, fallbackError.message);
          await delay(2000 * Math.pow(2, i));
      }
   }

   throw new Error(`Failed to write ${chapterLabel} after multiple attempts. Last error: ${lastError?.message}`);
};

export const refineChapterText = async (currentContent: string, instruction: string): Promise<string> => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: MODEL_FAST, // Use fast model for editing/polishing
      contents: {
        parts: [
          {
            text: `You are an expert book editor.

            Task: ${instruction}

            Current Text:
            ${currentContent}

            Return ONLY the rewritten text in Markdown format. Do not add conversational filler.`
          }
        ]
      }
    });
    return response.text || currentContent;
  } catch (error) {
    console.error("Refine text error:", error);
    if (isFatalError(error)) throw error;
    throw error;
  }
};

export const generateSpeech = async (text: string, voiceName: string = 'Kore'): Promise<string> => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: MODEL_TTS,
      contents: {
        parts: [{ text: text }]
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voiceName },
          },
        },
      },
    });

    const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!audioData) {
      throw new Error("No audio data generated");
    }
    return audioData;
  } catch (error) {
    console.error("TTS generation error:", error);
    return "";
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { BookProject, AppView, Source, SourceType, WritingStyle, ChapterContent } from './types';
import { Dashboard } from './components/Dashboard';
import { ProjectEditor } from './components/ProjectEditor';
import { writeChapter } from './services/gemini';
import { StorageService } from './services/storage';
import { Sparkles, Key } from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [projects, setProjects] = useState<BookProject[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);

  // API Key State
  const [hasApiKey, setHasApiKey] = useState(false);
  const [isKeyChecked, setIsKeyChecked] = useState(false);

  // Background Generation State
  const [generatingProjectId, setGeneratingProjectId] = useState<string | null>(null);
  const wakeLockRef = useRef<WakeLockSentinel | null>(null);

  // Initial Key Check
  useEffect(() => {
    const checkKey = async () => {
      try {
        if ((window as any).aistudio) {
            const hasKey = await (window as any).aistudio.hasSelectedApiKey();
            setHasApiKey(hasKey);
        } else {
            // If running outside IDX/AI Studio wrapper, assume true or rely on env var
            setHasApiKey(true);
        }
      } catch (e) {
        console.error("Failed to check API key", e);
        // Fallback to avoid locking user out if check fails mysteriously
        setHasApiKey(true);
      } finally {
        setIsKeyChecked(true);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    try {
      if ((window as any).aistudio) {
        await (window as any).aistudio.openSelectKey();
      }
      // Assume success immediately to avoid race condition delays
      setHasApiKey(true);
    } catch(e: any) {
      console.error(e);
      if (e.message && e.message.includes("Requested entity was not found")) {
        setHasApiKey(false);
      }
    }
  };

  // Initial Load from Storage
  useEffect(() => {
    const loadData = async () => {
      try {
        const loadedProjects = await StorageService.getAllProjects();
        setProjects(loadedProjects);

        const lastActiveId = await StorageService.getActiveProjectId();
        if (lastActiveId && loadedProjects.find(p => p.id === lastActiveId)) {
          setActiveProjectId(lastActiveId);
          setView(AppView.EDITOR);
          window.history.replaceState({ view: AppView.EDITOR, projectId: lastActiveId }, '');
        }
      } catch (e) {
        console.error("Failed to load data", e);
      } finally {
        setIsLoaded(true);
      }
    };
    loadData();
  }, []);

  // Save changes to Storage
  useEffect(() => {
    if (!isLoaded) return; // Prevent saving empty state over existing data during boot

    const saveData = async () => {
      try {
        await StorageService.saveAllProjects(projects);
        await StorageService.saveActiveProjectId(activeProjectId);
      } catch (e: any) {
        // IDB Quota errors are much rarer but possible if disk is full
        if (e.name === 'QuotaExceededError') {
           alert("⚠️ Disk Full! Your device storage is full. Please clear space to save your work.");
        } else {
           console.error("Failed to save project", e);
        }
      }
    };

    // Debounce save slightly to prevent thrashing
    const timeout = setTimeout(saveData, 500);
    return () => clearTimeout(timeout);
  }, [projects, activeProjectId, isLoaded]);

  // Handle Browser Back Button
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
      if (event.state && event.state.view === AppView.EDITOR) {
        setActiveProjectId(event.state.projectId);
        setView(AppView.EDITOR);
      } else {
        setActiveProjectId(null);
        setView(AppView.DASHBOARD);
      }
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  // --- Background Generator Logic ---

  const requestWakeLock = async () => {
    try {
      if ('wakeLock' in navigator) {
        wakeLockRef.current = await navigator.wakeLock.request('screen');
      }
    } catch (err) {
      console.error(`Wake Lock failed: ${err}`);
    }
  };

  const releaseWakeLock = async () => {
    if (wakeLockRef.current) {
      try {
        await wakeLockRef.current.release();
        wakeLockRef.current = null;
      } catch (err) {
        console.error(`Wake Lock release failed: ${err}`);
      }
    }
  };

  const startBookGeneration = async (projectId: string, style: WritingStyle) => {
    const project = projects.find(p => p.id === projectId);
    if (!project || !project.outline) return;

    setGeneratingProjectId(projectId);
    await requestWakeLock();

    // Sync chapters with outline: Preserve existing content, add new placeholders for new chapters
    // This allows users to add chapters in outline and have them generated without losing progress.
    const currentChapters: ChapterContent[] = project.outline.chapters.map(outlineChap => {
      const existing = project.chapters.find(c => c.chapterNumber === outlineChap.chapterNumber);
      if (existing) {
        // Update title if it changed in outline, keep content
        return { ...existing, title: outlineChap.title };
      }
      return {
        chapterNumber: outlineChap.chapterNumber,
        title: outlineChap.title,
        content: '',
        isGenerating: true
      };
    });

    // Update state to show loading spinners immediately for new/empty chapters
    handleUpdateProject({ ...project, chapters: currentChapters });

    let hasFatalError = false;

    // We use a functional update pattern in the loop to always get the LATEST project state
    for (const chapOutline of project.outline.chapters) {
      // Find the chapter in our (potentially updated via state) list
      // We check if we need to generate it.
      const chapterToGen = currentChapters.find(c => c.chapterNumber === chapOutline.chapterNumber);

      // If it exists, has content, and is NOT marked as generating, we skip it.
      // If it is marked as generating (newly added), we proceed.
      if (chapterToGen && chapterToGen.content && !chapterToGen.isGenerating) {
        continue;
      }

      if (hasFatalError) break;

      try {
        const content = await writeChapter(chapOutline, project.outline, project.sources, style);

        // Success: Update the specific chapter
        setProjects(prevProjects => prevProjects.map(p => {
          if (p.id !== projectId) return p;

          const updatedChapters = p.chapters.map(c => 
            c.chapterNumber === chapOutline.chapterNumber 
              ? { ...c, content, isGenerating: false }
              : c
          );

          return { ...p, chapters: updatedChapters, lastModified: Date.now() };
        }));

        // Update local reference for the loop logic
        // (Note: this local update doesn't affect the React state, just our loop's knowledge)
        const idx = currentChapters.findIndex(c => c.chapterNumber === chapOutline.chapterNumber);
        if (idx !== -1) {
            currentChapters[idx] = { ...currentChapters[idx], content, isGenerating: false };
        }

      } catch (e: any) {
         console.error(`Error generating chapter ${chapOutline.chapterNumber}`, e);
         const isFatal = e.message?.includes('leaked') || e.message?.includes('PERMISSION_DENIED') || e.status === 403;

         if (isFatal) {
             hasFatalError = true;
             alert(`Generation Stopped: ${e.message}`);
         }

         setProjects(prevProjects => prevProjects.map(p => {
            if (p.id !== projectId) return p;
            const updatedChapters = p.chapters.map(c => 
              c.chapterNumber === chapOutline.chapterNumber 
                ? { ...c, isGenerating: false, content: isFatal ? "Stopped due to API error." : "Generation failed. Please retry." }
                : c
            );
            return { ...p, chapters: updatedChapters };
         }));
      }
    }

    setGeneratingProjectId(null);
    await releaseWakeLock();
  };

  // --- End Generator Logic ---

  const handleCreateProject = () => {
    const newProject: BookProject = {
      id: crypto.randomUUID(),
      title: 'Untitled Manuscript',
      lastModified: Date.now(),
      sources: [],
      outline: null,
      chapters: [],
      currentStep: 0,
    };

    setProjects(prev => [newProject, ...prev]);
    setActiveProjectId(newProject.id);
    setView(AppView.EDITOR);
    window.history.pushState({ view: AppView.EDITOR, projectId: newProject.id }, '');
  };

  const handleCreateSequel = (originalProject: BookProject) => {
     const seriesId = originalProject.seriesId || crypto.randomUUID();
     const nextIndex = (originalProject.seriesIndex || 1) + 1;

     if (!originalProject.seriesId) {
        const updatedOriginal = { ...originalProject, seriesId, seriesIndex: 1 };
        handleUpdateProject(updatedOriginal);
     }

     const contextContent = `PREVIOUS BOOK CONTEXT:
Title: ${originalProject.title}
Description: ${originalProject.outline?.description || 'No description available.'}

CHAPTER SUMMARIES:
${originalProject.outline?.chapters.map(c => `Chapter ${c.chapterNumber}: ${c.title}\n${c.summary}`).join('\n\n') || 'No chapters available.'}
`;

    const contextSource: Source = {
      id: crypto.randomUUID(),
      type: SourceType.TEXT,
      name: `Context: ${originalProject.title}`,
      content: contextContent,
      isProcessing: false
    };

    const newProject: BookProject = {
      id: crypto.randomUUID(),
      title: `Sequel to ${originalProject.title}`,
      lastModified: Date.now(),
      sources: [contextSource],
      outline: null,
      chapters: [],
      currentStep: 0,
      seriesId: seriesId,
      seriesIndex: nextIndex
    };

    setProjects(prev => [newProject, ...prev]);
    setActiveProjectId(newProject.id);
    setView(AppView.EDITOR);
    window.history.pushState({ view: AppView.EDITOR, projectId: newProject.id }, '');
  };

  const handleUpdateProject = (updatedProject: BookProject) => {
    setProjects(prev => prev.map(p => p.id === updatedProject.id ? updatedProject : p));
  };

  const handleDeleteProject = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('Are you sure you want to delete this project? This action cannot be undone.')) {
      setProjects(prev => prev.filter(p => p.id !== id));
      if (activeProjectId === id) {
        setActiveProjectId(null);
        setView(AppView.DASHBOARD);
        window.history.replaceState({ view: AppView.DASHBOARD }, '');
      }
    }
  };

  const handleSelectProject = (project: BookProject) => {
    setActiveProjectId(project.id);
    setView(AppView.EDITOR);
    window.history.pushState({ view: AppView.EDITOR, projectId: project.id }, '');
  };

  const handleBackToDashboard = () => {
    setActiveProjectId(null);
    setView(AppView.DASHBOARD);
    window.history.pushState({ view: AppView.DASHBOARD }, '');
  };

  const activeProject = projects.find(p => p.id === activeProjectId);

