const CACHE_NAME = 'lore-cache-v3';
const urlsToCache = [
  '/',
  '/index.html',
  '/manifest.json',
  'https://cdn.tailwindcss.com',
  'https://cdn.tailwindcss.com?plugins=typography',
  'https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js',
  'https://cdn-icons-png.flaticon.com/512/3976/3976625.png'
];

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
  return self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // 1. Navigation Fallback for SPA (Single Page App)
  // If we are navigating to a new page (e.g. /some-route) and offline, return index.html
  if (event.request.mode === 'navigate') {
    event.respondWith(
      fetch(event.request).catch(() => {
        return caches.match('/index.html');
      })
    );
    return;
  }

  // 2. Ignore non-GET requests and browser extensions
  if (event.request.method !== 'GET' || !url.protocol.startsWith('http')) {
    return;
  }

  // 3. Stale-While-Revalidate Strategy
  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      // Create a promise to fetch from network and update cache
      const fetchPromise = fetch(event.request).then((networkResponse) => {
        if (networkResponse && networkResponse.status === 200) {
          const responseClone = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, responseClone);
          });
        }
        return networkResponse;
      }).catch((err) => {
         // Network failure
         return cachedResponse;
      });

      // Return cached response if available, otherwise fetch
      return cachedResponse || fetchPromise;
    })
  );
});

/**
 * Lore Cloud Backend
 * Handles User Auth (Sheets) and Book Storage (Drive).
 */

const SCRIPT_PROP = PropertiesService.getScriptProperties();
const SHEET_NAME = "LoreUsers";

function setup() {
  const doc = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = doc.getSheetByName(SHEET_NAME);
  if (!sheet) {
    sheet = doc.insertSheet(SHEET_NAME);
    sheet.appendRow(["Created", "Username", "PasswordHash", "FolderID"]);
    // Protect headers
    sheet.getRange(1, 1, 1, 4).setFontWeight("bold");
  }
}

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const data = JSON.parse(e.postData.contents);
    const action = data.action;

    if (action === "signup") return signUp(data);
    if (action === "login") return login(data);
    if (action === "syncUp") return saveProject(data);
    if (action === "syncDown") return loadProjects(data);

    return response({ status: "error", message: "Invalid action" });

  } catch (e) {
    return response({ status: "error", message: e.toString() });
  } finally {
    lock.releaseLock();
  }
}

// --- Auth Functions ---

function signUp(data) {
  const { username, password } = data;
  if (!username || !password) throw new Error("Missing credentials");

  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);
  const users = sheet.getDataRange().getValues();

  // Check duplicate
  const exists = users.find(r => r[1] === username);
  if (exists) throw new Error("Username already taken");

  // Create Drive Folder for User
  const folder = DriveApp.createFolder("Lore_Library_" + username);
  const folderId = folder.getId();

  // Simple Hash (Not enterprise secure, but sufficient for personal tools)
  const passHash = Utilities.base64Encode(password);

  sheet.appendRow([new Date(), username, passHash, folderId]);

  return response({ 
    status: "success", 
    username: username, 
    folderId: folderId,
    message: "Account created successfully"
  });
}

function login(data) {
  const { username, password } = data;
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);
  const users = sheet.getDataRange().getValues();

  const passHash = Utilities.base64Encode(password);
  const user = users.find(r => r[1] === username && r[2] === passHash);

  if (!user) throw new Error("Invalid username or password");

  return response({ 
    status: "success", 
    username: user[1], 
    folderId: user[3] 
  });
}

// --- Sync Functions ---

function saveProject(data) {
  const { folderId, project } = data;
  if (!folderId || !project) throw new Error("Missing data");

  const folder = DriveApp.getFolderById(folderId);
  const fileName = `lore_backup_${project.id}.json`;

  // Check if exists
  const files = folder.getFilesByName(fileName);
  if (files.hasNext()) {
    const file = files.next();
    file.setContent(JSON.stringify(project));
  } else {
    folder.createFile(fileName, JSON.stringify(project), "application/json");
  }

  return response({ status: "success", message: "Saved to Drive" });
}

function loadProjects(data) {
  const { folderId } = data;
  const folder = DriveApp.getFolderById(folderId);
  const files = folder.getFiles();
  const projects = [];

  while (files.hasNext()) {
    const file = files.next();
    if (file.getName().startsWith("lore_backup_")) {
      try {
        const json = JSON.parse(file.getBlob().getDataAsString());
        projects.push(json);
      } catch (e) {
        // Ignore corrupted files
      }
    }
  }

  return response({ status: "success", projects: projects });
}

// --- Helpers ---

function response(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}

